import { View, Text, TextInput, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

function App() {
  const [name, setName] = useState("");
  return (
    <View style={styles.screen}>
      <TextInput nativeID="field" style={styles.input} placeholder="Нэрээ бичнэ үү"
        value={name} onChangeText={setName} />
      {/* энд бичнэ үү: name хоосон бол анхааруулга Text харуул (nativeID="warn") */}
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, padding: 24, gap: 10, justifyContent: "center" },
  input: { borderWidth: 1, borderColor: "#cbd5e1", borderRadius: 10, padding: 14 },
  warn: { color: "#dc2626" },
});

registerRootComponent(App);

import { View, Text, TextInput, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

function App() {
  const [name, setName] = useState("");
  return (
    <View style={styles.screen}>
      <TextInput nativeID="field" style={styles.input} placeholder="Нэрээ бичнэ үү"
        value={name} onChangeText={setName} />
      {name.trim() === "" && <Text nativeID="warn" style={styles.warn}>Нэрээ заавал бичнэ үү</Text>}
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, padding: 24, gap: 10, justifyContent: "center" },
  input: { borderWidth: 1, borderColor: "#cbd5e1", borderRadius: 10, padding: 14 },
  warn: { color: "#dc2626" },
});

registerRootComponent(App);
